from itertools import product

# Try all possible assignments of 4 pigeons to 3 holes
# Each pigeon can be in hole 0, 1, or 2
solutions = []
for assignment in product(range(3), repeat=4):
    # Check if each hole has at most 1 pigeon
    hole_counts = [0, 0, 0]
    for pigeon_hole in assignment:
        hole_counts[pigeon_hole] += 1

    if all(count <= 1 for count in hole_counts):
        solutions.append(assignment)

print(f"Number of valid solutions: {len(solutions)}")
if solutions:
    print(f"First solution: {solutions[0]}")
else:
    print("No valid solution exists - UNSATISFIABLE")
